Cypress (15 and 16) helper for this template — in a Cypress suite, use it as written:
Facts:
  • hidden copies: each plan card also exists for other products — scoped by div[data-plan-type="teams"]
  • no attribute carries the plan name on every card (data-plan-name is empty on "Team") — a card is found by its toggle input's aria-label, else by its exact visible title
  • "Team Pro" shares the "Team" card behind a toggle: hidden radio inputs operated by their labels — showPlan(title) switches it
  • each card holds a hidden Choose and price per toggle state — act on the displayed one
  • the "Volume" card has no Choose button (its price line is promo text)
  • the toggle inputs are hidden: assert the selected state or the label text, not that the input exists — an existence check passes with nothing on screen
```js
const planCards = () => cy.get('div[data-plan-type="teams"] div.simplification-card');

const isPlan = (card, title) =>
  Cypress.$(card).find(`input.card-toggle__input[aria-label="${title}"]`).length > 0 ||
  Cypress.$(card).find('h3.simplification-card__title').text().trim() === title;

const planTitles = () =>
  Cypress.$('div[data-plan-type="teams"] div.simplification-card').toArray().flatMap((card) => {
    const toggles = Cypress.$(card).find('input.card-toggle__input').toArray().map((t) => t.getAttribute('aria-label'));
    return toggles.length ? toggles : [Cypress.$(card).find('h3.simplification-card__title').text().trim()];
  });

const cardOf = ($cards, title) => $cards.filter((_, card) => isPlan(card, title));
const oneCard = ($cards, title) => expect(cardOf($cards, title), `plan card titled "${title}" — plans on the page: ${planTitles().join(', ')}`).to.have.length(1);

const planCard = (title) =>
  planCards()
    .should(($cards) => oneCard($cards, title))
    .then(($cards) => cardOf($cards, title));

// Act, then wait for the state the act should produce: the toggle is checked.
const showPlan = (title) =>
  planCard(title).then(($card) => {
    const $toggle = $card.find(`input.card-toggle__input[aria-label="${title}"]`);
    if ($toggle.length && !$toggle.prop('checked')) cy.wrap($card).find(`label[for="${$toggle.attr('id')}"]`).click();
    if ($toggle.length) planCard(title).find(`input.card-toggle__input[aria-label="${title}"]`).should('be.checked');
  });

const inCard = (title, selector, what) =>
  planCards()
    .should(($cards) => {
      oneCard($cards, title);
      expect(cardOf($cards, title).find(selector).filter(':visible'), `plan "${title}": displayed ${what} in its card`).to.have.length(1);
    })
    .then(($cards) => cardOf($cards, title).find(selector).filter(':visible'));
const choose = (title) => inCard(title, 'input[type="submit"][value="Choose"]', 'Choose button');
const price = (title) => inCard(title, 'div.simplification-card__price', 'price');
```
