Cypress (15 and 16) helper for this template — in a Cypress suite, use it as written:
Facts:
  • hidden copies: each FAQ item exists twice; only the displayed items are the page's FAQ
  • no attribute carries the question — an item is found by its exact question text
  • an open question has the class "expanded" (the first is open on load)
```js
const QUESTION = 'p.pricing-redesign__faqs-section__faq-item__question';
const faqItems = () => cy.get('div.pricing-redesign__faqs-section__faq-item').filter(':visible');
const questionsOnPage = () =>
  Cypress.$('div.pricing-redesign__faqs-section__faq-item:visible').toArray().map((i) => Cypress.$(i).find(QUESTION).text().trim());
const itemOf = ($items, question) => $items.filter((_, item) => Cypress.$(item).find(QUESTION).text().trim() === question);
const faqItem = (question) =>
  faqItems()
    .should(($items) => expect(itemOf($items, question), `FAQ question "${question}" — questions on the page: ${questionsOnPage().join(' | ')}`).to.have.length(1))
    .then(($items) => itemOf($items, question));
const faqQuestion = (question) => faqItem(question).find(QUESTION);
const faqAnswer = (question) => faqItem(question).find('div.pricing-redesign__faqs-section__faq-item__answer-wrapper');

// Act, then wait for the state the act should produce: the answer is open.
const openFaq = (question) => {
  faqQuestion(question).then(($q) => { if (!$q.hasClass('expanded')) cy.wrap($q).click(); });
  faqQuestion(question).should('have.class', 'expanded');
};
```
