Cypress (15 and 16) helper for this template — in a Cypress suite, use it as written:
Facts:
  • column headers are in a separate table above the rows; plan names are h3.simplification-card__title, or a toggle input's aria-label ("Team" / "Team Pro" share a column)
  • hidden copies: every comparison table also exists for other products — scoped by div[data-plan-type="teams"]
  • the feature name is span.comparison-table__feature-name in the row's first cell
```js
const TEAMS_TABLES = 'div[data-plan-type="teams"] table.comparison-table__table';

const columnNames = () =>
  Cypress.$(`${TEAMS_TABLES} tr:first th`).toArray().map((th) => {
    const toggles = Cypress.$(th).find('input.card-toggle__input').toArray().map((t) => t.getAttribute('aria-label'));
    return toggles.length ? toggles.join(' / ') : Cypress.$(th).find('h3.simplification-card__title').text().trim() || '(feature names)';
  });

const isColumn = (th, column) =>
  Cypress.$(th).find(`input.card-toggle__input[aria-label="${column}"]`).length > 0 ||
  Cypress.$(th).find('h3.simplification-card__title').text().trim() === column;

const comparisonCell = (feature, column) =>
  cy.get(`${TEAMS_TABLES} tr`).first().find('th').then(($ths) => {
    const index = [...$ths].findIndex((th) => isColumn(th, column));
    expect(index, `comparison column "${column}" — columns: ${columnNames().join(', ')}`).to.be.greaterThan(-1);
    const rowOf = ($rows) => $rows.filter((_, tr) => Cypress.$(tr).find('span.comparison-table__feature-name').text().trim() === feature);
    return cy.get(`${TEAMS_TABLES} tr`)
      .should(($rows) => expect(rowOf($rows), `comparison row "${feature}"`).to.have.length(1))
      .then(($rows) => rowOf($rows).find('th, td').eq(index));
  });
```
